        raise ValueError('invalid limit')
    rows = sorted(events, key=lambda row: (row['sequence'], row['event_id']))
    if after is not None:
        rows = [row for row in rows
                if (row['sequence'], row['event_id']) > tuple(after)]
    selected = rows[:limit]
    cursor = None
